const labels={direct:"Прямий",adjacent:"Суміжний",attention:"За увагу"};let activeFilter="all";
const fmt=n=>n==null?"—":new Intl.NumberFormat("uk-UA").format(n);const pct=c=>c.online==null?null:(c.online/c.members*100);
function render(){const q=document.querySelector("#search").value.toLowerCase();const rows=competitors.filter(c=>(activeFilter==="all"||c.type===activeFilter)&&(`${c.name} ${c.focus}`.toLowerCase().includes(q))).sort((a,b)=>b.members-a.members);document.querySelector("#competitorRows").innerHTML=rows.map(c=>`<tr><td><strong>${c.name}</strong><span class="sub">${c.focus}</span></td><td><span class="pill">${labels[c.type]}</span></td><td class="num">${fmt(c.members)}</td><td class="num">${fmt(c.online)}</td><td class="num ${pct(c)?"rate":""}">${pct(c)?pct(c).toFixed(1)+"%":"—"}</td><td>${c.signal}</td><td><button class="more" data-name="${c.name}" aria-label="Деталі про ${c.name}">→</button></td></tr>`).join("");document.querySelectorAll(".more").forEach(b=>b.onclick=()=>openDetail(b.dataset.name))}
document.querySelectorAll(".segmented button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".segmented button").forEach(x=>x.classList.remove("active"));b.classList.add("active");activeFilter=b.dataset.filter;render()});document.querySelector("#search").addEventListener("input",render);
const dialog=document.querySelector("#detailDialog");function openDetail(name){const c=competitors.find(x=>x.name===name);document.querySelector("#dialogContent").innerHTML=`<span class="tag">${labels[c.type].toUpperCase()}</span><h2>${c.name}</h2><p>${c.focus}</p><div class="detail-metrics"><div><b>${fmt(c.members)}</b><span>учасники</span></div><div><b>${fmt(c.online)}</b><span>онлайн</span></div><div><b>${pct(c)?pct(c).toFixed(1)+"%":"—"}</b><span>presence ratio</span></div></div><div class="detail-grid"><div><h3>Що працює</h3><p>${c.strength}</p></div><div><h3>Вікно атаки</h3><p>${c.gap}</p></div></div><a class="detail-source" href="${c.source}" target="_blank" rel="noreferrer">Джерело: ${c.sourceName} ↗</a>`;dialog.showModal()}document.querySelector(".close").onclick=()=>dialog.close();dialog.addEventListener("click",e=>{if(e.target===dialog)dialog.close()});render();
const tooltip=document.querySelector("#mapTooltip");document.querySelectorAll(".bubble").forEach(b=>{b.addEventListener("pointerenter",()=>{tooltip.textContent=b.dataset.tip;tooltip.style.display="block"});b.addEventListener("pointermove",e=>{const r=document.querySelector(".map").getBoundingClientRect();tooltip.style.left=(e.clientX-r.left+12)+"px";tooltip.style.top=(e.clientY-r.top+12)+"px"});b.addEventListener("pointerleave",()=>tooltip.style.display="none")});
const acq=document.querySelector("#acq"),activation=document.querySelector("#activation"),retention=document.querySelector("#retention"),canvas=document.querySelector("#growthChart"),ctx=canvas.getContext("2d");function calc(){const a=+acq.value,act=+activation.value/100,r=+retention.value/100;acqOut.value=fmt(a);activationOut.value=activation.value+"%";retentionOut.value=retention.value+"%";let base=0,points=[];for(let m=1;m<=24;m++){base=base*r+a*act;points.push(base)}monthSix.textContent=fmt(Math.round(points[5]));monthTwelve.textContent=fmt(Math.round(points[11]));const hit=points.findIndex(v=>v>=3000);targetTime.textContent=hit<0?"> 24 міс.":(hit+1)+" міс.";draw(points)}function draw(points){const dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=260;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);ctx.strokeStyle="#263a33";ctx.lineWidth=1;for(let i=0;i<5;i++){const y=20+i*52;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}const max=Math.max(3000,...points)*1.1;ctx.beginPath();points.forEach((v,i)=>{const x=i/(points.length-1)*w,y=h-20-v/max*(h-40);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle="#b7f34a";ctx.lineWidth=3;ctx.stroke();ctx.lineTo(w,h-20);ctx.lineTo(0,h-20);ctx.closePath();const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,"rgba(183,243,74,.28)");g.addColorStop(1,"rgba(183,243,74,0)");ctx.fillStyle=g;ctx.fill()}[acq,activation,retention].forEach(x=>x.addEventListener("input",calc));window.addEventListener("resize",calc);calc();
